/* Look-ahead button for the Programme page (served as JS at cbs-lookahead-ui). Uses the page's programme data (window.D.p). */
function cbsLookahead(){
 if(window.__cbsLA)return;window.__cbsLA=1;
 var D=window.D||{},LOGO=null;
 function s(v){return v==null?'':String(v);}
 function e(t){return s(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
 function pd(x){return new Date(x+'T00:00:00Z');}function ds(d){return d.toISOString().slice(0,10);}
 function addD(x,n){var d=pd(x);d.setUTCDate(d.getUTCDate()+n);return ds(d);}
 function dd(a,b){return Math.round((pd(b)-pd(a))/86400000);}
 var DW=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
 function dmy(x){var m=s(x).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[3]+'/'+m[2]+'/'+m[1]:s(x);}
 function monday(x){var d=pd(x),w=d.getUTCDay();return addD(x,w===0?-6:1-w);}
 function today(){var d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);}
 function leaves(){var out=[],P=(D.p||{}).phases||[];P.forEach(function(p){if(!(p.tasks||[]).length){out.push({r:p,phase:p.name,path:p.name});return;}p.tasks.forEach(function(t){if(!(t.subs||[]).length){out.push({r:t,phase:p.name,path:t.name});return;}t.subs.forEach(function(x){out.push({r:x,phase:p.name,path:t.name+' \u203a '+x.name});});});});return out;}
 function add(){var pr=document.getElementById('pr');if(!pr||document.getElementById('laBtn'))return;var b=document.createElement('button');b.className='btn ghost';b.id='laBtn';b.textContent='Look-ahead';b.onclick=dlgLA;pr.parentNode.insertBefore(b,pr.nextSibling);}
 new MutationObserver(add).observe(document.body,{childList:true,subtree:true});add();
 function dlg(h){var o=document.createElement('div');o.className='ov';o.innerHTML='<div class="dlg">'+h+'</div>';document.body.appendChild(o);o.addEventListener('click',function(ev){if(ev.target===o)o.remove();});o.close=function(){o.remove();};return o;}
 function dlgLA(){var L=leaves();if(!L.length){alert('Add some tasks to the programme first.');return;}
  var st=monday(today());var people={};L.forEach(function(x){if(x.r.assigned_to)people[x.r.assigned_to]=1;});var P=Object.keys(people).sort();
  var o=dlg('<h2>Look-ahead</h2><div class="m">The work coming up, by day, for site and subcontractors.</div>'
   +'<div class="row2"><div><label class="f">Starting</label><input type="date" id="las" value="'+st+'"></div><div><label class="f">Length</label><select id="law"><option value="1">1 week</option><option value="2" selected>2 weeks</option><option value="3">3 weeks</option><option value="4">4 weeks</option></select></div></div>'
   +'<label class="f">Who</label><select id="lap"><option value="">Everyone</option>'+P.map(function(p){return '<option>'+e(p)+'</option>';}).join('')+'</select>'
   +'<label class="chk"><input type="checkbox" id="lawe"><span>Include weekends</span></label>'
   +'<label class="chk"><input type="checkbox" id="lad" checked><span>Leave out work already done</span></label>'
   +'<label class="chk"><input type="checkbox" id="lal" checked><span>Add a day-by-day list after the chart</span></label>'
   +'<div class="note" id="lam"></div><div class="b"><button class="btn" id="lag">Download PDF</button><button class="btn ghost" id="lax">Cancel</button></div>');
  o.querySelector('#lax').onclick=o.close;
  o.querySelector('#lag').onclick=function(){var a=o.querySelector('#las').value;if(!a){alert('Pick the start date.');return;}if(!window.jspdf){alert('The PDF tool did not load. Refresh and try again.');return;}
   var opt={from:a,weeks:Number(o.querySelector('#law').value)||2,who:o.querySelector('#lap').value,we:o.querySelector('#lawe').checked,hideDone:o.querySelector('#lad').checked,list:o.querySelector('#lal').checked};
   var b=this;b.disabled=true;getLogo().then(function(lg){var n=build(opt,lg);if(!n){b.disabled=false;o.querySelector('#lam').textContent='Nothing is planned in that window'+(opt.who?' for '+opt.who:'')+'.';return;}o.close();});};}
 function getLogo(){if(LOGO!==null)return Promise.resolve(LOGO);return fetch('/webhook/cbs-programme-logo').then(function(r){return r.json();}).then(function(d){LOGO=(d&&d.lg)||'';return LOGO;}).catch(function(){LOGO='';return '';});}
 function build(opt,lg){var to=addD(opt.from,opt.weeks*7-1),days=[],i;for(i=0;i<opt.weeks*7;i++){var d=addD(opt.from,i),w=pd(d).getUTCDay();if(opt.we||(w>0&&w<6))days.push(d);}
  var rows=leaves().filter(function(x){var r=x.r,a=r.start_eff,b=r.end_eff||a;if(!a||b<opt.from||a>to)return false;if(opt.hideDone&&r.status_eff==='Done')return false;if(opt.who&&s(r.assigned_to)!==opt.who)return false;return true;})
   .sort(function(x,y){return s(x.r.start_eff).localeCompare(s(y.r.start_eff))||s(x.phase).localeCompare(s(y.phase));});
  if(!rows.length)return 0;
  var doc=new window.jspdf.jsPDF({orientation:'landscape',unit:'mm',format:'a4'}),W=297,HH=210,M=10,LW=92,X0=M+LW,X1=W-M,cw=(X1-X0)/days.length,TD=today(),y;
  var where=[D.site,D.client].filter(Boolean).join('  |  ');
  function head(){doc.setFillColor(244,121,32);doc.rect(0,0,W,3,'F');var lx=M;if(lg){try{var pr=doc.getImageProperties(lg),hh=13,ww=pr.width*hh/pr.height;if(ww>48){ww=48;hh=pr.height*ww/pr.width;}doc.addImage(lg,'PNG',M,7,ww,hh);lx=M+ww+5;}catch(z){}}
   doc.setTextColor(30);doc.setFont('helvetica','bold');doc.setFontSize(15);doc.text(opt.weeks+'-week look-ahead - Job '+D.job,lx,12);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.setTextColor(90);doc.text((where||'Chelmsford Building Services').slice(0,110)+(opt.who?'  |  '+opt.who:''),lx,17.5);
   doc.text(dmy(opt.from)+' to '+dmy(to),X1,12,{align:'right'});doc.text('Chelmsford Building Services Ltd  |  Printed '+new Date().toLocaleDateString('en-GB'),X1,17.5,{align:'right'});
   var ty=24;doc.setFontSize(7.5);days.forEach(function(d,k){var x=X0+k*cw,w=pd(d).getUTCDay();if(w===1||k===0){doc.setDrawColor(150);doc.setLineWidth(0.3);doc.line(x,ty,x,HH-14);}
    if(w===0||w===6){doc.setFillColor(243,243,241);doc.rect(x,ty+9,cw,HH-14-(ty+9),'F');}if(d===TD){doc.setFillColor(253,228,208);doc.rect(x,ty,cw,9,'F');}
    doc.setFont('helvetica','bold');doc.setTextColor(60);doc.text(DW[w],x+cw/2,ty+3.6,{align:'center'});doc.setFont('helvetica','normal');doc.setTextColor(100);doc.text(d.slice(8,10)+'/'+d.slice(5,7),x+cw/2,ty+7.4,{align:'center'});});
   doc.setFont('helvetica','bold');doc.setFontSize(8);doc.setTextColor(80);doc.text('Task (phase)',M+1,ty+5.5);doc.text('Who',M+62,ty+5.5);doc.setDrawColor(150);doc.setLineWidth(0.3);doc.line(M,ty+9,X1,ty+9);doc.line(X0,ty,X0,HH-14);doc.setLineWidth(0.2);return ty+9;}
  y=head();var lastPh='';
  rows.forEach(function(x){var r=x.r,rh=7;if(y+rh>HH-14){doc.addPage();y=head();lastPh='';}
   if(x.phase!==lastPh){if(y+12>HH-14){doc.addPage();y=head();}doc.setFillColor(250,250,248);doc.rect(M,y,X1-M,5.5,'F');doc.setFont('helvetica','bold');doc.setFontSize(8);doc.setTextColor(40);doc.text(s(x.phase),M+1,y+3.9);y+=5.5;lastPh=x.phase;}
   doc.setFont('helvetica','normal');doc.setFontSize(7.8);doc.setTextColor(25);doc.text((doc.splitTextToSize(x.path,58)[0]||''),M+3,y+4.6);doc.setTextColor(80);doc.text((doc.splitTextToSize(s(r.assigned_to),28)[0]||''),M+62,y+4.6);
   var c=r.status_eff==='Done'?[95,174,110]:(r.status_eff==='In progress'?[244,121,32]:[150,152,154]);
   days.forEach(function(d,k){if(d>=r.start_eff&&d<=(r.end_eff||r.start_eff)){doc.setFillColor(c[0],c[1],c[2]);doc.rect(X0+k*cw+0.4,y+1.6,cw-0.8,3.8,'F');}});
   if(r.overdue){doc.setTextColor(179,38,30);doc.setFontSize(6.5);doc.text('overdue',M+88,y+4.6,{align:'right'});}
   doc.setDrawColor(232);doc.line(M,y+rh,X1,y+rh);y+=rh;});
  if(opt.list){doc.addPage();y=18;doc.setFont('helvetica','bold');doc.setFontSize(13);doc.setTextColor(30);doc.text('Day by day',M,y);y+=6;
   days.forEach(function(d){var on=rows.filter(function(x){return d>=x.r.start_eff&&d<=(x.r.end_eff||x.r.start_eff);});if(!on.length)return;
    if(y>HH-24){doc.addPage();y=18;}doc.setFont('helvetica','bold');doc.setFontSize(10);doc.setTextColor(30);doc.text(DW[pd(d).getUTCDay()]+' '+dmy(d),M,y);y+=5;
    on.forEach(function(x){var r=x.r,tag=d===r.start_eff?'Starts':(d===(r.end_eff||r.start_eff)?'Finishes':'Continues');if(y>HH-14){doc.addPage();y=18;}
     doc.setFont('helvetica','normal');doc.setFontSize(8.5);doc.setTextColor(40);doc.text('- '+tag+': '+x.path+' ('+x.phase+')'+(r.assigned_to?'  -  '+r.assigned_to:''),M+3,y);y+=4.4;});y+=2;});}
  var np=doc.getNumberOfPages();for(var k=1;k<=np;k++){doc.setPage(k);doc.setFont('helvetica','normal');doc.setFontSize(7.5);doc.setTextColor(90);var lx=M,ly=HH-7;
   [[[150,152,154],'Not started'],[[244,121,32],'In progress'],[[95,174,110],'Done']].forEach(function(q){doc.setFillColor(q[0][0],q[0][1],q[0][2]);doc.rect(lx,ly-2.6,5,3,'F');doc.text(q[1],lx+6.5,ly);lx+=doc.getTextWidth(q[1])+14;});
   doc.text('Page '+k+' of '+np,X1,ly,{align:'right'});}
  doc.save('Job '+D.job+' - Look-ahead '+opt.from+'.pdf');return rows.length;}
}

